<span class="line"><span style="color:#ABB2BF;">            torch.nn.utils.</span><span style="color:#61AFEF;">clip_grad_norm_</span><span style="color:#ABB2BF;">(model.</span><span style="color:#61AFEF;">parameters</span><span style="color:#ABB2BF;">(), </span><span style="color:#D19A66;">1.0</span><span style="color:#ABB2BF;">)</span></span>
