<span class="line"><span style="color:#ABB2BF;">    save_cfg </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> FullStateDictConfig</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;font-style:italic;">offload_to_cpu</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">True</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;font-style:italic;">rank0_only</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">True</span><span style="color:#ABB2BF;">)</span></span>
